package org.beyondlight;
import java.util.*;import java.time.*;
/** Explicitly staged feasibility checks. Passing a stage never implies success at a later stage. */
public final class FeasibilityEngine {
 public static final String MAT_VALID="MATHEMATICALLY_VALIDATED",MAT_BAD="MATHEMATICALLY_INCONSISTENT",PHYS_OK="PHYSICALLY_SUPPORTED_WITHIN_MODEL",PHYS_BAD="PHYSICAL_VIOLATION_DETECTED",ENG_OK="ENGINEERINGALLY_PLAUSIBLE_WITH_AVAILABLE_DATA",ENG_BAD="ENGINEERINGALLY_INFEASIBLE",MISSING="INSUFFICIENT_DATA",NUMERIC="NUMERICALLY_INCONCLUSIVE",THEORY="THEORETICAL_ONLY",EXPERIMENT="REQUIRES_EXPERIMENTAL_VALIDATION";
 public record Check(String law,String status,String reasoning,String equation,Map<String,Object>inputs,Double residual,String tolerance){}
 public record Stage(String status,List<Check>checks,String assumptions,String limitations){}
 public record Assessment(String id,String date,String modelVersion,String propulsionFamily,Stage mathematical,Stage conservation,Stage energyThermal,Stage engineering,Map<String,Object>results,String overallClassification){}
 public record Stress(double tensilePa,double compressivePa,double shearPa,double vonMisesPa,double strain,double axialDeformationM,Double safetyFactor,String status,List<String>unknowns){}
 public record Electrical(double powerW,double currentA,double voltageV,double resistanceOhm,double jouleHeatW,double energyJ,String status){}
 public record EnergyStorage(double deliveredEnergyJ,double requiredInputEnergyJ,double conversionLossJ,double minimumStorageMassKg,String status){}
 public record Thermal(double conductionW,double radiationW,double netRejectedW,double requiredHeatW,double marginW,String status,List<String>unknowns){}
 public record EnergyCondition(String status,boolean nullEnergyCondition,boolean weakEnergyCondition,String reasoning){}
 private FeasibilityEngine(){}
 public static Check energyBalance(Double beforeJ,Double afterJ,double relTol){return balance("energy conservation",beforeJ,afterJ,relTol,"E_initial = E_final; include all stores, fluxes and losses inside the chosen boundary");}
 public static Check chargeBalance(Double beforeC,Double afterC,double absTol){String eq="Q_initial = Q_final for an isolated system boundary";if(beforeC==null||afterC==null)return new Check("charge conservation",MISSING,"Required initial and final charges are missing",eq,Map.of(),null,"not evaluated");if(!Double.isFinite(beforeC)||!Double.isFinite(afterC)||absTol<0||!Double.isFinite(absTol))return new Check("charge conservation",NUMERIC,"Nonfinite input or invalid absolute tolerance",eq,Map.of(),null,"invalid");double r=beforeC-afterC;return new Check("charge conservation",Math.abs(r)<=absTol?PHYS_OK:PHYS_BAD,Math.abs(r)<=absTol?"Charge balance closes within absolute tolerance":"Charge residual exceeds absolute tolerance",eq,Map.of("initial_C",beforeC,"final_C",afterC),r,Double.toString(absTol));}
 private static Check balance(String law,Double a,Double b,double tol,String eq){if(a==null||b==null)return new Check(law,MISSING,"Required initial and final values are missing",eq,Map.of(),null,"not evaluated");if(!Double.isFinite(a)||!Double.isFinite(b)||tol<0||!Double.isFinite(tol))return new Check(law,NUMERIC,"Nonfinite input or invalid tolerance",eq,Map.of(),null,"invalid");double r=a-b,threshold=tol*Math.max(1,Math.max(Math.abs(a),Math.abs(b)));return new Check(law,Math.abs(r)<=threshold?PHYS_OK:PHYS_BAD,Math.abs(r)<=threshold?"Balance closes within configured numerical tolerance":"Balance residual exceeds configured tolerance",eq,Map.of("initial",a,"final",b),r,Double.toString(threshold));}
 public static Check vectorBalance(String law,double[]before,double[]after,double tol,String unit){if(before==null||after==null)return new Check(law,MISSING,"Initial or final vector missing","vector_initial = vector_final",Map.of(),null,"not evaluated");if(before.length!=3||after.length!=3)return new Check(law,MAT_BAD,"Expected three vector components","p_initial = p_final",Map.of(),null,"invalid vector shape");double norm=0,scale=1;for(int i=0;i<3;i++){if(!Double.isFinite(before[i])||!Double.isFinite(after[i]))return new Check(law,NUMERIC,"Nonfinite vector component","vector_initial = vector_final",Map.of(),null,"invalid");norm+=Math.pow(before[i]-after[i],2);scale=Math.max(scale,Math.max(Math.abs(before[i]),Math.abs(after[i])));}double r=Math.sqrt(norm),t=tol*scale;return new Check(law,r<=t?PHYS_OK:PHYS_BAD,r<=t?"Vector balance closes within tolerance":"Vector residual exceeds tolerance","vector_initial = vector_final",Map.of("unit",unit,"initial",Arrays.stream(before).boxed().toList(),"final",Arrays.stream(after).boxed().toList()),r,Double.toString(t));}
 public static Check relativisticInvariant(double massKg,double energyJ,double[]momentum,double relTol){if(momentum==null)return new Check("relativistic energy-momentum",MISSING,"Momentum vector missing","E²−|p|²c² = m²c⁴",Map.of(),null,"not evaluated");if(momentum.length!=3||massKg<0||!Double.isFinite(energyJ)||!Double.isFinite(massKg))return new Check("relativistic energy-momentum",MAT_BAD,"Invalid mass, energy, or momentum vector","E²−|p|²c² = m²c⁴",Map.of(),null,"invalid");double p2=0;for(double p:momentum){if(!Double.isFinite(p))return new Check("relativistic energy-momentum",NUMERIC,"Nonfinite momentum","E²−|p|²c² = m²c⁴",Map.of(),null,"invalid");p2+=p*p;}double c=Physics.C,res=energyJ*energyJ-p2*c*c-massKg*massKg*Math.pow(c,4);double scale=Math.max(1,energyJ*energyJ),tol=relTol*scale;return new Check("relativistic energy-momentum",Math.abs(res)<=tol?PHYS_OK:PHYS_BAD,Math.abs(res)<=tol?"Invariant matches within tolerance":"Energy-momentum invariant mismatch","E²−|p|²c² = m²c⁴",Map.of("mass_kg",massKg,"energy_J",energyJ,"momentum_kg_m_s",Arrays.stream(momentum).boxed().toList()),res,Double.toString(tol));}
 public static Stress stress(double tensileN,double compressiveN,double shearN,double areaM2,double shearAreaM2,double lengthM,double youngPa,double yieldPa,double safetyRequired){List<String>unknown=new ArrayList<>();if(!Double.isFinite(tensileN)||!Double.isFinite(compressiveN)||!Double.isFinite(shearN)||tensileN<0||compressiveN<0||areaM2<=0||shearAreaM2<=0||lengthM<0||youngPa<=0||safetyRequired<=0)throw new IllegalArgumentException("finite nonnegative loads, positive areas/modulus/safety factor and nonnegative length required");double st=tensileN/areaM2,sc=compressiveN/areaM2,ss=shearN/shearAreaM2,normal=st-sc,strain=normal/youngPa,def=strain*lengthM,vm=Math.sqrt(normal*normal+3*ss*ss);Double sf;if(yieldPa<=0||!Double.isFinite(yieldPa)){unknown.add("yield strength/allowable unavailable");sf=null;}else sf=yieldPa/vm;String status=unknown.size()>0?MISSING:sf>=safetyRequired?ENG_OK:ENG_BAD;return new Stress(st,sc,ss,vm,strain,def,sf,status,List.copyOf(unknown));}
 public static double eulerBucklingLoad(double youngPa,double secondMomentM4,double lengthM,double effectiveLengthFactor){if(youngPa<=0||secondMomentM4<=0||lengthM<=0||effectiveLengthFactor<=0)throw new IllegalArgumentException("Euler inputs must be positive");return Math.PI*Math.PI*youngPa*secondMomentM4/Math.pow(effectiveLengthFactor*lengthM,2);}
 public static double pressureHoopStress(double pressurePa,double radiusM,double wallM){if(pressurePa<0||radiusM<=0||wallM<=0)throw new IllegalArgumentException("pressure nonnegative and radius/wall positive required");if(wallM/radiusM>.1)throw new IllegalArgumentException("thin-wall approximation requires wall/radius <= 0.1");return pressurePa*radiusM/wallM;}
 public static double thermalExpansion(double alphaPerK,double lengthM,double deltaK){if(alphaPerK<0||lengthM<0||!Double.isFinite(alphaPerK)||!Double.isFinite(lengthM)||!Double.isFinite(deltaK))throw new IllegalArgumentException("invalid expansion inputs");return alphaPerK*lengthM*deltaK;}
 public static Electrical electrical(double voltage,double current,double resistance,double duration){if(voltage<0||current<0||resistance<0||duration<0||!Double.isFinite(voltage)||!Double.isFinite(current)||!Double.isFinite(resistance)||!Double.isFinite(duration))throw new IllegalArgumentException("electrical inputs must be finite and nonnegative");double p=voltage*current,ohm=current*current*resistance,energy=p*duration;String status=resistance==0?MISSING:Math.abs(voltage-current*resistance)<=1e-8*Math.max(1,voltage)?PHYS_OK:PHYS_BAD;return new Electrical(p,current,voltage,resistance,ohm,energy,status);}
 public static Thermal thermal(double conductivity,double area,double deltaT,double thickness,double emissivity,double tempK,double ambientK,double requiredHeatW,double coolingW){List<String>u=new ArrayList<>();double conduction=Physics.conductionPower(conductivity,area,deltaT,thickness),rad=Physics.radiativePower(emissivity,area,tempK,ambientK),rejected=conduction+rad;if(requiredHeatW<0||coolingW<0)throw new IllegalArgumentException("heat requirements nonnegative");double margin=coolingW-rejected-requiredHeatW;String status=coolingW==0?MISSING:margin>=0?ENG_OK:ENG_BAD;if(coolingW==0)u.add("cooling system capacity not supplied");return new Thermal(conduction,rad,rejected,requiredHeatW,margin,status,List.copyOf(u));}
 public static EnergyStorage assessEnergyStorage(double deliveredEnergyJ,double energyDensityJkg,double conversionEfficiency){if(!Double.isFinite(deliveredEnergyJ)||!Double.isFinite(energyDensityJkg)||!Double.isFinite(conversionEfficiency)||deliveredEnergyJ<0||energyDensityJkg<=0||conversionEfficiency<=0||conversionEfficiency>1)throw new IllegalArgumentException("finite energy>=0, energy density>0 and 0<efficiency<=1 required");double input=deliveredEnergyJ/conversionEfficiency,loss=input-deliveredEnergyJ,mass=deliveredEnergyJ/energyDensityJkg;if(!Double.isFinite(input+loss+mass))throw new IllegalArgumentException("energy storage calculation overflow");return new EnergyStorage(deliveredEnergyJ,input,loss,mass,MISSING);}
 public static Electrical energyStorage(double energyJ,double energyDensityJkg,double conversionEfficiency){if(energyJ<0||energyDensityJkg<=0||conversionEfficiency<=0||conversionEfficiency>1)throw new IllegalArgumentException("invalid energy storage inputs");return new Electrical(energyJ*conversionEfficiency,0,0,0,energyJ*(1-conversionEfficiency),energyJ/conversionEfficiency,MISSING);}
 public static EnergyCondition diagonalEnergyConditions(double rhoJm3,double[]pressures){if(pressures==null||pressures.length!=3||!Double.isFinite(rhoJm3))throw new IllegalArgumentException("provide finite rho and three principal pressures");boolean nec=true,wec=rhoJm3>=0;for(double p:pressures){if(!Double.isFinite(p))throw new IllegalArgumentException("nonfinite pressure");if(rhoJm3+p<0)nec=false;}wec=wec&&nec;return new EnergyCondition(nec&&wec?PHYS_OK:PHYS_BAD,nec,wec,"Diagonal orthonormal-frame test only: NEC rho+p_i>=0; WEC rho>=0 and rho+p_i>=0. Not a stress-energy tensor derived from a metric.");}
 public static Assessment assess(String family,double dryKg,double payloadKg,double dv,double isp,double thrust,double efficiency,double duration,double availablePowerW,double coolingW,MachineDesign.Assembly assembly){String f=family.toLowerCase(Locale.ROOT);List<Check>math=new ArrayList<>(),cons=new ArrayList<>(),energy=new ArrayList<>(),eng=new ArrayList<>();Map<String,Object>out=new LinkedHashMap<>();String matStatus=MAT_VALID,physical=PHYS_OK,energyStatus=PHYS_OK,engineering=assembly==null?MISSING:assembly.classification();boolean valid=Double.isFinite(dryKg)&&dryKg>0&&Double.isFinite(payloadKg)&&payloadKg>=0&&Double.isFinite(dv)&&dv>=0&&Double.isFinite(isp)&&isp>0&&Double.isFinite(thrust)&&thrust>=0&&Double.isFinite(efficiency)&&efficiency>0&&efficiency<=1&&Double.isFinite(duration)&&duration>=0&&Double.isFinite(availablePowerW)&&availablePowerW>=0&&Double.isFinite(coolingW)&&coolingW>=0;Map<String,Object>input=new LinkedHashMap<>();input.put("dry_kg",dryKg);input.put("payload_kg",payloadKg);input.put("delta_v_m_s",dv);input.put("isp_s",isp);input.put("thrust_N",thrust);input.put("efficiency",efficiency);input.put("duration_s",duration);input.put("available_power_W",availablePowerW);input.put("cooling_W",coolingW);math.add(new Check("input domain",valid?MAT_VALID:MAT_BAD,valid?"All values finite and within the model-specific positive/nonnegative domain":"Invalid or nonfinite input; mass>0, payload/delta-v/thrust/duration/power/cooling>=0, Isp>0, 0<efficiency<=1 required","SI input-domain validation",input,null,"exact checks"));if(!valid){Stage badMath=new Stage(MAT_BAD,List.copyOf(math),"SI units","Model evaluation skipped because an input is outside its domain");Stage missing=new Stage(MISSING,List.of(new Check("assessment unavailable",MISSING,"Physical and engineering stages require valid model inputs","not evaluated",Map.of(),null,"not evaluated")),"not evaluated","not evaluated");return new Assessment(UUID.randomUUID().toString(),Instant.now().toString(),"beyond-light-0.4",family,badMath,missing,missing,missing,Map.of(),MAT_BAD);}boolean spacetime=f.contains("warp")||f.contains("spacetime")||f.contains("wormhole");boolean photon=f.contains("photon");boolean reaction=Set.of("chemical","electric","ion","hall","plasma","nuclear thermal","nuclear electric","fusion (reaction)").contains(f);
  if(spacetime){matStatus=THEORY;physical=MISSING;energyStatus=MISSING;engineering=THEORY;math.add(new Check("spacetime model",THEORY,"Metric geometry is not a propulsion thrust or energy-source model","No validated vehicle performance equation supplied",Map.of("family",family),null,"not applicable"));cons.add(new Check("momentum transfer",MISSING,"No demonstrated reaction mass, photon beam, or validated field momentum flux supplied","Momentum conservation requires a defined control volume and flux",Map.of(),null,"not evaluated"));energy.add(new Check("available energy",MISSING,"A metric does not supply usable energy; no supported source or stress-energy production mechanism supplied","No energy-source model",Map.of(),null,"not evaluated"));}
  else if(photon){if(thrust<=0||duration<=0||efficiency<=0||efficiency>1){matStatus=MAT_BAD;physical=NUMERIC;}else{double p=thrust*Physics.C/efficiency,e=p*duration;out.put("photon_thrust_N",thrust);out.put("beam_power_W",p);out.put("beam_energy_J",thrust*Physics.C*duration);out.put("input_energy_J",e);out.put("propellant_kg",null);out.put("delta_v",null);matStatus=MAT_VALID;cons.add(new Check("photon momentum",PHYS_OK,"Ideal collimated photons transfer momentum at F=P_beam/c","F=P_beam/c",Map.of("thrust_N",thrust,"beam_power_W",p),0d,"ideal collimation; no absorption/recoil system modeled"));energy.add(new Check("photon energy",PHYS_OK,"Beam power calculated from momentum flux and efficiency","P_input=F*c/eta",Map.of("input_power_W",p,"duration_s",duration),0d,"idealized beam"));energy.add(energyBalance(e,thrust*Physics.C*duration+e-thrust*Physics.C*duration,1e-9));physical=PHYS_OK;engineering=MISSING;}math.add(new Check("photon propulsion domain",MAT_VALID,"Photon rocket handled by momentum-energy relation; chemical rocket equation not applied","F=P/c",Map.of("family",family),null,"relativistic photon-rocket mass-ratio delta-v not implemented"));}
  else if(reaction){try{Core.Propulsion p=Core.propulsion(dryKg,payloadKg,dv,isp,thrust,efficiency);out.put("thrust_N",p.thrustN());out.put("exhaust_velocity_m_s",p.exhaustVelocity());out.put("mass_flow_kg_s",p.massFlowKgS());out.put("delta_v_m_s",p.deltaV());out.put("propellant_kg",p.propellantKg());out.put("initial_mass_kg",p.initialMassKg());out.put("burn_duration_s",p.burnSeconds());out.put("kinetic_power_W",p.kineticPowerW());out.put("input_power_W",p.electricalPowerW());double burn=Math.min(duration>0?duration:p.burnSeconds(),p.burnSeconds()),in=p.electricalPowerW()*burn,kin=p.kineticPowerW()*burn,waste=in-kin;math.add(new Check("ideal rocket relation",MAT_VALID,"Existing SI model evaluated within finite positive domain","ve=Isp*g0; delta-v=ve ln(m0/mf)",Map.of("Isp_s",isp,"exhaust_velocity_m_s",p.exhaustVelocity(),"delta_v_m_s",p.deltaV()),0d,"no gravity, drag, staging or variable exhaust velocity"));cons.add(new Check("reaction momentum flux",Math.abs(p.thrustN()-p.massFlowKgS()*p.exhaustVelocity())<1e-8*Math.max(1,p.thrustN())?PHYS_OK:PHYS_BAD,"Checks thrust equals exhaust momentum flow","F=mdot*ve",Map.of("F_N",p.thrustN(),"mdot_kg_s",p.massFlowKgS(),"ve_m_s",p.exhaustVelocity()),p.thrustN()-p.massFlowKgS()*p.exhaustVelocity(),"floating-point tolerance"));cons.add(energyBalance(in,kin+waste,1e-9));energy.add(new Check("energy conversion",waste>=-1e-9?PHYS_OK:PHYS_BAD,"Equivalent exhaust kinetic energy and efficiency-derived waste heat","P_input=P_kin/eta; Qdot=P_input-P_kin",Map.of("input_J",in,"exhaust_kinetic_J",kin,"waste_heat_J",waste,"duration_s",burn),in-kin-waste,"ideal exhaust kinetic power only; not detailed engine thermodynamics"));if(availablePowerW<=0){energy.add(new Check("power source",MISSING,"Available continuous power rating missing","P_available >= P_input",Map.of("required_W",p.electricalPowerW()),null,"not evaluated"));energyStatus=MISSING;}else{double residual=availablePowerW-p.electricalPowerW();energy.add(new Check("power source",residual>=0?PHYS_OK:ENG_BAD,residual>=0?"Rated power covers calculated load":"Rated power below calculated load","P_available >= P_input",Map.of("available_W",availablePowerW,"required_W",p.electricalPowerW()),residual,"continuous ratings assumed"));if(residual<0)energyStatus=ENG_BAD;}if(assembly!=null){for(String miss:assembly.missing())eng.add(new Check("component requirements",MISSING,miss,"component material/geometry check",Map.of(),null,"source property absent"));for(String err:assembly.dependencyErrors())eng.add(new Check("component dependency",MAT_BAD,err,"dependency id must resolve",Map.of(),null,"exact ID check"));eng.add(new Check("machine mass/power aggregate",assembly.missing().isEmpty()?ENG_OK:MISSING,assembly.classification(),"sum component mass, power, energy and heat",Map.of("component_mass_kg",assembly.massKg(),"component_power_W",assembly.powerW(),"component_energy_J",assembly.energyJ(),"component_heat_W",assembly.heatW()),null,"not a structural or manufacturing certification"));if(!assembly.missing().isEmpty())engineering=MISSING;else engineering=ENG_OK;}}catch(Exception e){matStatus=MAT_BAD;physical=NUMERIC;math.add(new Check("propulsion model",MAT_BAD,e.getMessage(),"existing reaction propulsion equations",Map.of("family",family),null,"calculation rejected"));}}
  else{matStatus=THEORY;physical=MISSING;energyStatus=MISSING;engineering=MISSING;math.add(new Check("propulsion family",THEORY,"No family-specific validated performance model is implemented; conventional rocket equations were not substituted","family-specific equations required",Map.of("family",family),null,"not implemented"));}
  if(energyStatus.equals(PHYS_OK)&&coolingW<=0){energy.add(new Check("heat rejection",MISSING,"Cooling capacity not supplied; calculated efficiency loss cannot be assumed dissipated","Qdot_waste <= cooling rating",Map.of(),null,"not evaluated"));energyStatus=MISSING;}else if(coolingW>0&&out.containsKey("input_power_W")){double waste=(double)out.get("input_power_W")*(1-efficiency),margin=coolingW-waste;energy.add(new Check("heat rejection",margin>=0?PHYS_OK:ENG_BAD,margin>=0?"Cooling rating covers calculated idealized waste heat":"Cooling rating below idealized waste heat","Qdot_reject >= P_input-P_kin",Map.of("cooling_W",coolingW,"estimated_waste_heat_W",waste),margin,"engine heat model reduced to efficiency difference"));if(margin<0)energyStatus=ENG_BAD;}
  Stage ms=new Stage(matStatus,List.copyOf(math),"SI units; finite inputs; model-specific equations only",spacetime?"No metric-to-thrust mapping":"Symbolic candidate relation is not independently experimentally established");Stage cs=new Stage(physical,List.copyOf(cons),"Conservation applies to defined isolated/control-volume boundaries","Unmodeled external fluxes may change balances");Stage es=new Stage(energyStatus,List.copyOf(energy),"Efficiency is user supplied; waste heat estimate uses ideal exhaust kinetic power","Energy-source cycle, storage mass and thermal gradients not modeled");Stage ens=new Stage(engineering,List.copyOf(eng),"Only stored component volumes, densities and declared power/time/heat are aggregated","No machine assembly alone establishes manufacturability");String overall=spacetime?THEORY:(!math.isEmpty()&&matStatus.equals(MAT_VALID)&&physical.equals(PHYS_OK)&&energyStatus.equals(PHYS_OK)&&engineering.equals(ENG_OK))?EXPERIMENT:(!physical.equals(PHYS_BAD)&&!energyStatus.equals(ENG_BAD)?MISSING:PHYS_BAD);return new Assessment(UUID.randomUUID().toString(),Instant.now().toString(),"beyond-light-0.4",family,ms,cs,es,ens,Collections.unmodifiableMap(out),overall);}
}
